 "content": "def transform(grid):
    """Mark each separator-bounded panel that contains multiple non-background cells."""
    h, w = len(grid), len(grid[0])
    # Separator color is the color whose full rows/columns divide the grid.
    sep_candidates = set(grid[0])
    sep = next((c for c in sep_candidates
                if any(all(v == c for v in row) for row in grid)), None)
    if sep is None:
        sep = next(c for c in set(grid[0])
                   if any(all(grid[r][j] == c for r in range(h)) for j in range(w)))
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            if start < r:
                row_bands.append((start, r))
            start = r + 1
    if start < h:
        row_bands.append((start, h))
    col_bands = []
    start = 0
    for c in range(w):
        if all(grid[r][c] == sep for r in range(h)):
            if start < c:
                col_bands.append((start, c))
            start = c + 1
    if start < w:
        col_bands.append((start, w))
    # The most frequent color within the panels is the background; other colors
    # are the marks whose counts determine the output.
    from collections import Counter
    counts = Counter(grid[r][c] for r0, r1 in row_bands for c0, c1 in col_bands
                     for r in range(r0, r1) for c in range(c0, c1))
    background = counts.most_common(1)[0][0]
    out = [[background for _ in col_bands] for _ in row_bands]
    for i, (r0, r1) in enumerate(row_bands):
        for j, (c0, c1) in enumerate(col_bands):
            marks = sum(grid[r][c] != background
                        for r in range(r0, r1) for c in range(c0, c1))
            if marks > 1:
                out[i][j] = 1
    return out
